mapper.select:
SELECT dict_value AS dictValue, SUM(contact_count)::bigint AS contactCount, SUM(lead_count)::bigint AS leadCount FROM ( SELECT t.id AS dict_value, COUNT(DISTINCT c.contact_id)::bigint AS contact_count, 0::bigint AS lead_count FROM crm_contact c CROSS JOIN LATERAL unnest(crm_tag_ids(c.tag::text)) AS t(id)
AND t.id = #{dictValue}
GROUP BY t.id UNION ALL SELECT t.id AS dict_value, 0::bigint AS contact_count, COUNT(DISTINCT l.lead_id)::bigint AS lead_count FROM crm_lead l CROSS JOIN LATERAL unnest(crm_tag_ids(l.tag::text)) AS t(id)
AND t.id = #{dictValue}
GROUP BY t.id ) u GROUP BY dict_value ORDER BY dict_value

SELECT #{dictValue} AS dictValue,
       COALESCE((
           SELECT COUNT(DISTINCT c.contact_id)
           FROM crm_contact c
           CROSS JOIN LATERAL unnest(crm_tag_ids(c.tag::text)) AS t(id)
           WHERE t.id = #{dictValue}
       ), 0)::bigint AS contactCount,
       COALESCE((
           SELECT COUNT(DISTINCT l.lead_id)
           FROM crm_lead l
           CROSS JOIN LATERAL unnest(crm_tag_ids(l.tag::text)) AS t(id)
           WHERE t.id = #{dictValue}
       ), 0)::bigint AS leadCount

