INSERT INTO crm_tag_dispatch_task (
    segment_id, dict_value, channel, channel_tag_id, app_id, status,
    total, succeeded, failed, error_message, create_by, create_time, update_time
) VALUES (
    #{segmentId}, #{dictValue}, #{channel}, #{channelTagId}, #{appId}, #{status},
    #{total}, #{succeeded}, #{failed}, #{errorMessage}, #{createBy}, #{createTime}, #{updateTime}
)
